private int _thumbnailRefreshVersion;
private readonly Dictionary<int, Task<string?>> _thumbnailDownloads = new Dictionary<int, Task<string?>>();

internal async void UpdateThumbnails()
{
    var version = ++_thumbnailRefreshVersion;
    var modsByNexusId = Mods.Select(mod => (Mod: mod, Id: mod.NexusModId))
        .Where(item => item.Id.HasValue)
        .ToLookup(item => item.Id!.Value, item => item.Mod);
    try
    {
        var directory = Pathing.GetThumbnailsPath();
        var cached = await Task.Run(() => Directory.Exists(directory)
            ? Directory.EnumerateFiles(directory).ToLookup(Path.GetFileNameWithoutExtension, StringComparer.OrdinalIgnoreCase)
            : Enumerable.Empty<string>().ToLookup(Path.GetFileNameWithoutExtension, StringComparer.OrdinalIgnoreCase));

        // Yield between batches so opening the window and scrolling take priority over decoding images.
        foreach (var batch in modsByNexusId.Chunk(24))
        {
            await Dispatcher.UIThread.InvokeAsync(() =>
            {
                if (version != _thumbnailRefreshVersion || !Program.settings.ShowModThumbnails)
                {
                    return;
                }
                foreach (var mods in batch)
                {
                    var path = cached[mods.Key.ToString()].FirstOrDefault();
                    if (path is not null)
                    {
                        foreach (var mod in mods)
                        {
                            mod.NexusModThumbnailPath = path;
                        }
                    }
                }
            }, DispatcherPriority.Background);
            if (version != _thumbnailRefreshVersion || !Program.settings.ShowModThumbnails)
            {
                return;
            }
        }

        foreach (var mods in modsByNexusId)
        {
            var client = Nexus.Client;
            if (version != _thumbnailRefreshVersion || !Program.settings.ShowModThumbnails || client is null)
            {
                return;
            }
            if (cached.Contains(mods.Key.ToString()) || mods.All(mod => mod.NexusModThumbnailPath is not null))
            {
                continue;
            }
            if (!_thumbnailDownloads.TryGetValue(mods.Key, out var download))
            {
                download = client.DownloadThumbnail(mods.Key);
                _thumbnailDownloads.Add(mods.Key, download);
            }
            var path = await download;
            if (version != _thumbnailRefreshVersion || !Program.settings.ShowModThumbnails)
            {
                return;
            }
            if (path is not null)
            {
                foreach (var mod in mods)
                {
                    mod.NexusModThumbnailPath = path;
                }
            }
        }
    }
    catch (Exception ex)
    {
        Program.helper.Log($"Could not refresh mod thumbnails: {ex}", Helper.Status.Warning);
    }
}

