private async void ModGrid_DoubleClick(object? sender, PointerPressedEventArgs e)
{
    if (e.ClickCount != 2 || e.KeyModifiers != KeyModifiers.None || e.Source is not IVisual source
        || e.GetCurrentPoint(this).Properties.PointerUpdateKind != PointerUpdateKind.LeftButtonPressed
        || source.FindAncestorOfType<DataGridRow>(includeSelf: true)?.DataContext is not Mod mod)
    {
        return;
    }

    if (source.GetSelfAndVisualAncestors().OfType<Grid>().Any(control => control.Classes.Contains("modThumbnail")))
    {
        e.Handled = true;
        await PickModThumbnail(mod);
    }
    else if (source.FindAncestorOfType<Button>(includeSelf: true) is null
        && source.FindAncestorOfType<TextBox>(includeSelf: true) is null
        && !e.Handled && mod.ModFileInfo.DirectoryName is string directory)
    {
        e.Handled = true;
        OpenNativeExplorer(directory);
    }
}

private async Task PickModThumbnail(Mod mod)
{
    if (_isPickingThumbnail)
    {
        return;
    }

    _isPickingThumbnail = true;
    var identity = mod.ToReference();
    try
    {
        var title = String.Format(Program.translation.Get("ui.main_window.thumbnail.choose"), mod.Name);
        var dialog = new OpenFileDialog
        {
            Title = title,
            Directory = mod.ModFileInfo.DirectoryName
        };
        dialog.Filters.Add(new FileDialogFilter
        {
            Name = Program.translation.Get("ui.main_window.thumbnail.images"),
            Extensions = { "png", "jpg", "jpeg", "webp", "bmp", "gif" }
        });
        var paths = await dialog.ShowAsync(this);
        if (paths is not { Length: > 0 })
        {
            return;
        }

        await Task.Run(() => CustomModThumbnail.Save(identity, paths[0]));
        foreach (var currentMod in _viewModel.Mods.Where(identity.Matches))
        {
            currentMod.RefreshCustomThumbnail();
        }
    }
    catch (Exception ex)
    {
        Program.helper.Log($"Could not save custom thumbnail for {identity}: {ex}", Helper.Status.Warning);
        await CreateWarningWindow(Program.translation.Get("ui.main_window.thumbnail.failed"), Program.translation.Get("internal.ok"));
    }
    finally
    {
        _isPickingThumbnail = false;
    }
}

private async void NoteCell_PointerPressed(object? sender, PointerPressedEventArgs e)
{
    if (e.Source is not IVisual source
        || (e.KeyModifiers & (KeyModifiers.Shift | KeyModifiers.Control)) != 0
        || source.GetSelfAndVisualAncestors().OfType<Grid>().FirstOrDefault(grid => grid.Classes.Contains("noteCell")) is not Grid cell
        || cell.DataContext is not Mod mod
        || !e.GetCurrentPoint(cell).Properties.IsLeftButtonPressed)
    {
        return;
    }

    var editor = cell.Children.OfType<TextBox>().Single();
    if (e.ClickCount == 2)
    {
        e.Handled = true;
        if (editor.IsVisible)
        {
            FinishInlineNote(editor, save: true);
        }
        await EditModNote(mod);
    }
    else if (!editor.IsVisible)
    {
        e.Handled = true;
        BeginInlineNote(editor, mod);
    }
}

private static void BeginInlineNote(TextBox editor, Mod mod)
{
    if (editor.IsVisible || editor.Parent is not Grid cell)
    {
        return;
    }

    editor.Tag = mod;
    editor.Text = mod.Note ?? String.Empty;
    editor.IsVisible = true;
    cell.Children.OfType<Button>().Single().Opacity = 0;
    editor.Focus();
    editor.CaretIndex = editor.Text.Length;
}

private async void NotePreview_KeyDown(object? sender, KeyEventArgs e)
{
    if (sender is Button { DataContext: Mod mod } button && button.Parent is Grid cell)
    {
        if (e.Key == Key.Enter)
        {
            e.Handled = true;
            await EditModNote(mod);
        }
        else if (e.Key == Key.F2)
        {
            e.Handled = true;
            BeginInlineNote(cell.Children.OfType<TextBox>().Single(), mod);
        }
    }
}

private void InlineNote_KeyDown(object? sender, KeyEventArgs e)
{
    if (sender is not TextBox editor)
    {
        return;
    }

    if (e.Key == Key.Escape)
    {
        e.Handled = true;
        FinishInlineNote(editor, save: false);
    }
    else if (e.Key == Key.Enter && e.KeyModifiers.HasFlag(KeyModifiers.Control))
    {
        e.Handled = true;
        FinishInlineNote(editor, save: true);
    }
}

private void InlineNote_LostFocus(object? sender, RoutedEventArgs e)
{
    if (sender is TextBox editor)
    {
        FinishInlineNote(editor, save: true);
    }
}

private void InlineNote_DataContextChanged(object? sender, EventArgs e)
{
    // The grid may recycle an editing row while scrolling or rebuilding the list.
    if (sender is TextBox { Tag: Mod edited } editor && !ReferenceEquals(editor.DataContext, edited))
    {
        FinishInlineNote(editor, save: true);
    }
}

private void FinishInlineNote(TextBox editor, bool save)
{
    if (editor.Tag is not Mod mod)
    {
        return;
    }

    var note = editor.Text;
    editor.Tag = null;
    editor.IsVisible = false;
    if (editor.Parent is Grid cell)
    {
        cell.Children.OfType<Button>().Single().Opacity = 1;
    }
    if (save && note is not null)
    {
        SaveModNote(mod, note);
    }
}

private async Task EditModNote(Mod mod)
{
    var note = await new ModNoteWindow(mod.Name, mod.Note ?? String.Empty).ShowDialog<string?>(this);
    if (note is not null)
    {
        SaveModNote(mod, note);
    }
}

private async void SaveModNote(Mod mod, string note)
{
    var normalized = note.ReplaceLineEndings("\n");
    if (normalized == (mod.Note ?? String.Empty).ReplaceLineEndings("\n"))
    {
        return;
    }

    try
    {
        SharedModNotes.Set(mod.UniqueId, normalized);
    }
    catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
    {
        Program.helper.Log($"Could not save the shared note: {ex}");
        await CreateWarningWindow(Program.translation.Get("ui.note_window.save_failed"), Program.translation.Get("internal.ok"));
        return;
    }

    foreach (var copy in _viewModel.Mods.Where(copy => copy.UniqueId.Equals(mod.UniqueId, StringComparison.OrdinalIgnoreCase)))
    {
        copy.Note = normalized;
    }
}

