private async Task<string?> RenameCustomCategory(string category, Window owner)
{
    var name = await new CategoryNamingWindow(category, true).ShowDialog<string?>(owner);
    if (String.IsNullOrWhiteSpace(name))
    {
        return null;
    }

    if (!Program.customCategories.Rename(category, name))
    {
        var warning = new WarningWindow(
            Program.translation.Get("ui.main_window.menu_items.context.custom_category_rename_failed"),
            Program.translation.Get("internal.ok"));
        await warning.ShowDialog(owner);
        return null;
    }

    var newPath = Program.customCategories.Normalize(name);
    var groupingIsCustom = Program.settings.ModGroupingMethod == ModGrouping.Custom;
    PreserveModGrid(_viewModel.ReapplyCustomCategories, path =>
        groupingIsCustom && (path.Equals(category, StringComparison.OrdinalIgnoreCase)
            || path.StartsWith(category + CustomCategoryStore.Separator, StringComparison.OrdinalIgnoreCase))
            ? newPath + path.Substring(category.Length) : path);
    return newPath;
}

